    DOMAIN_ERROR: 400,
    AUTHENTICATION_ERROR: 401,
    AUTHORIZATION_ERROR: 403,
    NOT_FOUND: 404,
    INVALID_INPUT: 422,
    RATE_LIMITED: 429,
    INTERNAL_ERROR: 500,
